FROM ( SELECT group_id, line_supplier_id, GROUP_CONCAT(DISTINCT gateway_id ORDER BY gateway_id SEPARATOR ',') as gateway_ids, price, effect_start_date, effect_end_date, create_time, update_time, enabled, is_delete, MAX(CASE WHEN gateway_id IN(0
#{gatewayId}
) THEN 1 ELSE 0 END) as has_target_gateway FROM b_marketing_line_account_detail_normal
is_delete = 0 AND line_supplier_id = #{lineSupplierId} AND price = #{price} AND #{nowDate} BETWEEN effect_start_date AND effect_end_date
GROUP BY group_id, price, effect_start_date ) t WHERE 1=1
AND has_target_gateway = 1
